Console.WriteLine("First line\nSecond line");

if (Brain.Oxygen <= 0) {
    Console.WriteLine("Out of air");
} else if (Brain.Hunger < 2) {
    Console.WriteLine("Hungry");
} else {
    Console.WriteLine("Stable");
}

for (int pulse = 0; pulse < 3; pulse++) {
    Console.WriteLine("Pulse " + pulse);
    Brain.Wait(20);
}

int mode = 1;
switch (mode) {
    case 0:
        Console.WriteLine("Rest");
        break;
    case 1:
    case 2:
        Console.WriteLine("Observe");
        break;
    default:
        Console.WriteLine("Unknown mode");
        break;
}

for (int count = 0; count < 6; count++) {
    if (count == 1) {
        continue;
    }
    if (count == 4) {
        break;
    }
    Console.WriteLine(count);
}
return;

double health = Brain.Health;
double hunger = Brain.Hunger;
double air = Brain.Oxygen;
double tick = Brain.Tick;
Console.WriteLine("HP " + health + ", food " + hunger);
Console.WriteLine("Air " + air + ", tick " + tick);

using System;
class Program {
    static void Main() {
        while (true) {
            Console.WriteLine("Health: " + Brain.Health);
            Console.WriteLine("Hunger: " + Brain.Hunger);
            Console.WriteLine("Oxygen: " + Brain.Oxygen);
            if (Brain.Oxygen <= 0) {
                Console.WriteLine("Warning: no air!");
            }
            Brain.Wait(20);
        }
    }
}
